'use strict';

import { createError, MISSING_DOC } from 'pouchdb-errors';

import { idbError, META_STORE } from './util';

export default function (txn, doc, callback) {
  if (txn.error) {
    return callback(txn.error);
  }

  const id = doc._id;

  const objectStore = txn.txn.objectStore(META_STORE);

  const get = objectStore.get(id);
  get.onerror = idbError(callback);
  get.onsuccess = function (e) {
    const oldDoc = e.target.result;
    if (!oldDoc || oldDoc.rev !== doc._rev) {
      callback(createError(MISSING_DOC));
    } else {
      const del = objectStore.delete(id);
      del.onerror = idbError(callback);
      del.onsuccess = function () {
        callback(null, {ok: true, id: id, rev: '0-0'});
      };
    }
  };
}
